function validate([nums, cost]) {
  if (!Array.isArray(nums) || !Array.isArray(cost)) return 'nums and cost must be arrays.';
  if (nums.length !== cost.length) return 'nums and cost must have the same length.';
  if (nums.length < 1 || nums.length > 100000) return 'n is between 1 and 10^5.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each nums[i] is an integer from 1 to 10^6.';
  if (cost.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each cost[i] is an integer from 1 to 10^6.';
  const order = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b]);
  const total = cost.reduce((s, c) => s + c, 0);
  let run = 0, target = nums[order[0]];
  for (const i of order) { run += cost[i]; if (2 * run >= total) { target = nums[i]; break; } }
  let answer = 0;
  for (let i = 0; i < nums.length; i++) answer += Math.abs(nums[i] - target) * cost[i];
  if (answer > Number.MAX_SAFE_INTEGER) return 'The answer must stay at most 2^53 - 1.';
  return null;
}

