function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000));
    const cost = Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000));
    return [nums, cost];
  }
  const n = 1 + Math.floor(rand() * 7);
  const span = rand() < 0.5 ? 5 : 30;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  const cost = Array.from({ length: n }, () => 1 + Math.floor(rand() * (rand() < 0.3 ? 100 : 6)));
  return [nums, cost];
}
